        <tr><td>{{ r.id }}</td><td>{{ carName(r.car) }}</td><td>{{ r.rating }}</td>
          <td><button (click)="remove(r)">Delete</button></td></tr>
      }
    </tbody>
  </table>
  @if (editing) {
    <div class="overlay"></div>
    <div class="popup">
      <h3>Rating</h3>
      <label>Car <select [(ngModel)]="carIdx">
        @for (c of cars; track $index) { <option [ngValue]="$index">{{ carName(c) }}</option> }
      </select></label>
      <label>Rating <input id="gwt-debug-ratingInput" type="text" [(ngModel)]="value" /></label>
      <div>
        <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
        <button (click)="editing = false">Close</button>
      </div>
    </div>
  }`,
})
export class RatingComponent implements OnInit {
  private http = inject(HttpClient); private msgs = inject(MessagesService);
  carName = carName;
  list: RatingDto[] = []; cars: CarDto[] = [];
  editing = false; carIdx = 0; value = '';
  ngOnInit() {
    this.http.get<RatingDto[]>(API + '/ratings').subscribe({
      next: l => this.list = l, error: () => this.msgs.error('An error occurred while loading ratings') });
  }
  open() {
    this.http.get<CarDto[]>(API + '/cars').subscribe({
      next: c => { this.cars = c; this.carIdx = 0; this.value = ''; this.editing = true; },
      error: () => this.msgs.error('An error occurred while loading cars') });
  }
  save() {
    const n = parseInt(this.value, 10);
    const dto: RatingDto = { rating: isNaN(n) ? null : n, car: this.cars[this.carIdx] ?? null };
    this.http.post<RatingDto>(API + '/ratings', dto).subscribe({
      next: saved => { this.editing = false; this.msgs.success('Rating saved'); this.list = [...this.list, saved]; },
      error: () => this.msgs.error('An error occurred while saving the rating'),
    });
  }
  remove(r: RatingDto) {
    if (!window.confirm('Are you sure you want to delete this rating?')) return;
    this.http.delete(API + '/ratings/' + r.id).subscribe({
      next: () => { this.list = this.list.filter(x => x !== r); this.msgs.success('Rating deleted'); },
      error: () => this.msgs.error('An error occurred while deleting the rating'),
    });
  }
}
