import { Component, inject, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { API, ManufacturerRatingDto, RatingDto } from './api';
import { MessagesService } from './messages.service';
@Component({
  standalone: true,
  template: `
  <h2>Reports</h2>
  <table id="gwt-debug-reports" class="grid">
    <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
    <tbody>
      @for (r of list; track $index) { <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr> }
    </tbody>
  </table>`,
})
export class ReportComponent implements OnInit {
  private http = inject(HttpClient); private msgs = inject(MessagesService);
  list: ManufacturerRatingDto[] = [];
  ngOnInit() {
    this.http.get<ManufacturerRatingDto[]>(API + '/manufacturers/ratings').subscribe({
      next: l => this.list = l, error: () => this.fallback() });
  }
  private fallback() {
    this.http.get<RatingDto[]>(API + '/ratings').subscribe({
      next: rs => {
        const m = new Map<string, number[]>();
        for (const r of rs) { const k = r.car?.manufacturer?.name ?? ''; if (!m.has(k)) m.set(k, []); m.get(k)!.push(r.rating ?? 0); }
        this.list = [...m].map(([manufacturer, v]) => ({ manufacturer, rating: v.reduce((a, b) => a + b, 0) / v.length }));
      },
      error: () => this.msgs.error('An error occurred while loading reports') });
  }
}
